// TypeScript interface for theme colors
export interface ThemeColors {
  bgPrimary: string;
  bgSecondary: string;
  accentColor: string;
  accentHover: string;
  accentColorRgb: string;
}

// TypeScript interface for theme data
export interface Theme {
  id: string;
  name: string;
  description: string;
  colors: ThemeColors;
  preview: string[];
  icon: string;
}

